// Edge factory. source = influenced, target = influence (arrow -> root).
// citation added as a 5th, optional, trailing param — every pre-existing
// inf() call (region-one/electronic/folk-confessional) omits it and keeps
// getting citation: null exactly as before; only new (emo-realm) calls pass
// a real source string. Additive, not a breaking change to any existing edge.
const inf = (
  source: string,
  target: string,
  confidence = 0.8,
  status: Edge['status'] = 'verified',
  citation: string | null = null,
): Edge => ({ source, target, type: 'influence', status, confidence, citation });

